<script setup lang="ts">import {computed} from 'vue';import type {Corpus,Run,Profile,Note} from '../types/domain';import PageTitle from '../components/common/PageTitle.vue';import TopicTerms from '../components/TopicTerms.vue';import RunSummary from '../components/RunSummary.vue';import RunTable from '../components/RunTable.vue';import Empty from '../components/common/Empty.vue';const props=defineProps<{corpora:Corpus[];runs:Run[];profiles:Profile[];notes:Note[]}>();defineEmits<{select:[run:Run]}>();const latest=computed(()=>props.runs.find(r=>r.status==='succeeded')),topics=computed(()=>props.profiles.filter(p=>p.run_id===latest.value?.id));</script><template><PageTitle index="01 / EDITORIAL OVERVIEW" title="主题成形之后，解释仍待编辑。" description="先固定语料、词汇与K，再阅读词权、文档相对激活和多初始化对齐；重建误差与语义质量分开。"><a href="#config" class="button primary">建立主题研究 ↗</a></PageTitle><div class="overview-grid"><section class="topic-feature"><header><small>LATEST VOLUME / 最近完成</small><span>{{latest?.name||'等待独立分解'}}</span></header><TopicTerms v-if="topics[0]" :profile="topics[0]"/><Empty v-else title="还没有主题词权" help="先核对空白分词语料，再选择K与重复次数。"/><RunSummary v-if="latest" :run="latest"/><button v-if="latest" class="text-button" @click="$emit('select',latest)">阅读全部主题与初始化匹配 →</button></section><aside class="editorial-margin"><small>SOURCE & JUDGEMENT</small><div class="source-count"><b>{{corpora.reduce((n,c)=>n+c.document_count,0).toLocaleString()}}</b><span>分词文档<small>{{corpora.length}}份语料批次</small></span></div><div class="topic-index"><div v-for="p in topics" :key="p.id"><small>{{String(p.topic_index+1).padStart(2,'0')}}</small><span>{{p.label}}</span></div></div><blockquote>稳定的词组，<br/>也需要人来读。<p>多初始化相似度只说明对起点的敏感性。主题名、解释与下一步由编辑给出。</p></blockquote><p class="approved-count">已确认编辑说明 {{notes.filter(n=>n.status==='approved').length}} 份</p></aside></div><div class="section-title"><h2>主题册索引</h2><small>K预先选择，不按跨K误差自动择优</small></div><RunTable :runs="runs.slice(0,5)" @select="$emit('select',$event)"/></template>
